mapper.select:
select date_format(checkin_date, '%Y-%m-%d') as checkinDate,
       date_format(checkin_time, '%Y-%m-%d %H:%i:%s') as checkinTime,
       actions
from erp_checkin
where user_id = #{userId}
  and checkin_date >= #{start}
  and checkin_date <= #{end}
order by checkin_date asc

select date_format(login_time, '%Y-%m-%d') as day, count(1) as amount
from sys_logininfor
where user_name = #{userName}
  and status = '0'
  and login_time >= #{start}
  and login_time < #{end}
group by date_format(login_time, '%Y-%m-%d')

select date_format(oper_time, '%Y-%m-%d') as day, count(1) as amount
from sys_oper_log
where oper_name = #{userName}
  and oper_time >= #{start}
  and oper_time < #{end}
group by date_format(oper_time, '%Y-%m-%d')
